export const getAppApiUsageApplicationIdIndexRoute = createRoute({
  method: 'get',
  path: '/App/ApiUsage/{applicationId}/',
  tags: ['App'],
  description:
    'Get API usage by application for time frame specified. You can go as far back as 30 days ago, and can ask for up to a 48 hour window of time in a single request. You must be authenticated with at least the ReadUserData permission to access this endpoint.',
  operationId: 'App.GetApplicationApiUsage',
  request: {
    params: z.object({
      applicationId: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .openapi({
          param: {
            name: 'applicationId',
            in: 'path',
            description: 'ID of the application to get usage statistics.',
            required: true,
            schema: { type: 'integer', format: 'int32' },
          },
        }),
    }),
    query: z.object({
      end: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'end',
            in: 'query',
            description: 'End time for query. Goes to now if not specified.',
            schema: { type: 'string', format: 'date-time' },
            required: false,
          },
        }),
      start: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'start',
            in: 'query',
            description: 'Start time for query. Goes to 24 hours ago if not specified.',
            schema: { type: 'string', format: 'date-time' },
            required: false,
          },
        }),
    }),
  },
  responses: { 200: ApplicationsApiUsageResponse },
  security: [{ oauth2: ['ReadUserData'] }],
})

